@dataclass(frozen=True)
class CADDiagnostics:
    cell_count_by_level: Mapping[int, int]
    proj_poly_count_by_level: Mapping[int, int]
    max_stack_size: int
    timing_by_stage: Mapping[str, float] = field(default_factory=dict)
    invariant_failures: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "cell_count_by_level", freeze_mapping(self.cell_count_by_level))
        object.__setattr__(
            self, "proj_poly_count_by_level", freeze_mapping(self.proj_poly_count_by_level)
        )
        object.__setattr__(self, "timing_by_stage", freeze_mapping(self.timing_by_stage))


@dataclass(frozen=True)
class CompleteCAD:
    tower: ProjectionTower
    cells_by_level: Mapping[int, tuple[CADCell, ...]]
    complete: bool = True
    backend: str = "collins-complete"
    diagnostics: CADDiagnostics | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "cells_by_level", freeze_mapping(self.cells_by_level))

    @property
    def cells(self) -> tuple[CADCell, ...]:
        return self.cells_by_level.get(len(self.tower.variables), tuple())

    def cell_count_by_level(self) -> dict[int, int]:
        return {level: len(cells) for level, cells in self.cells_by_level.items()}

    def proj_poly_count_by_level(self) -> dict[int, int]:
        return self.tower.poly_count_by_level()

    def max_stack_size(self) -> int:
        max_size = 0
        for level, cells in self.cells_by_level.items():
            if level == 1:
                max_size = max(max_size, len(cells))
                continue
            counts: dict[tuple[int, ...] | None, int] = {}
            for cell in cells:
                counts[cell.parent_index] = counts.get(cell.parent_index, 0) + 1
            if counts:
                max_size = max(max_size, max(counts.values()))
        return max_size

    def verify_sign_invariance(self) -> SignInvarianceCheck:
        return verify_cad_sign_inv(self.cells_by_level, self.tower)

    def failed_invariants(self) -> tuple[str, ...]:
        return self.verify_sign_invariance().failures


@dataclass(frozen=True)
class TowerFiberSpecialization:
    """A fiber polynomial specialized into a certified algebraic parent tower.

    Rational and certified point coordinates have already been substituted.
    Remaining parent variables denote the selected ordered algebraic tower; they
    are never reconstructed as primitive elements or ``CRootOf`` expressions.
    """

    expression: sp.Expr
    variables: tuple[sp.Symbol, ...]
    parent_samples: tuple[AlgebraicRoot, ...]
    fiber_variable: sp.Symbol

    def context(self) -> FiberRootContext:
        return FiberRootContext(
            polynomial=sp.Poly(self.expression, *self.variables, domain=sp.QQ),
            variables=self.variables,
            parent_samples=self.parent_samples,
            fiber_variable=self.fiber_variable,
        )


def _sample_for_fiber_arithmetic(sample: Sample) -> sp.Expr:
    """Return an existing exact coefficient representation without reconstruction.

    CAD lifting may reuse a representation obtained during root isolation, but
    it must not manufacture a global primitive element merely to specialize the
    next fiber.  Opaque parent-aware roots are handled by tower certificates.
    """
    from ..algebraic.samples import RationalSample, local_tower_root_expr

    if isinstance(sample, RationalSample):
        return sample.value
    if sample.root_expr is not None:
        return sample.root_expr
    if sample.interval.is_point():
        # A non-nullified point interval is an exact rational root certificate.
        # This avoids recursively reconstructing an otherwise opaque parent tower.
        if sample.fiber_context is None or not sample.fiber_context.is_nullified_at_parent():
            return sample.interval.left
    if sample.fiber_context is None and sample.polynomial.domain in (sp.ZZ, sp.QQ):
        return sp.CRootOf(sample.polynomial.as_expr(), sample.root_index)
    if sample.fiber_context is not None:
        exact = local_tower_root_expr(sample)
        if exact is not None:
            return exact
    raise ArithmeticError(
        "fiber specialization requires a tower coefficient operation for an opaque parent root"
    )


def _specialize_fiber_polynomial(
    poly: sp.Poly, variables: Sequence[sp.Symbol], prefix: Sequence[Sample]
) -> sp.Expr | TowerFiberSpecialization:
    """Specialize a lifting polynomial without reconstructing algebraic parents.

    Exact rational/point coordinates are substituted immediately.  If genuinely
    algebraic parent coordinates remain, the result stays in their ordered
    triangular quotient tower and is returned as ``TowerFiberSpecialization``.
    """
    key = (
        "cad-fiber",
        poly_key(poly),
        tuple(sample_identity_key(sample) for sample in prefix),
    )
    cached = CACHE.specializations.get(key)
    if cached is not None:
        CACHE.stats.specialization_hits += 1
        return cached
    CACHE.stats.specialization_misses += 1

    substitutions: dict[sp.Symbol, sp.Rational] = {}
    active_variables: list[sp.Symbol] = []
    active_samples: list[AlgebraicRoot] = []
    for index, sample in enumerate(prefix):
        variable = variables[index]
        if isinstance(sample, RationalSample):
            substitutions[variable] = sample.value
        elif isinstance(sample, AlgebraicRoot) and sample.interval.is_point():
            substitutions[variable] = sample.interval.left
        elif isinstance(sample, AlgebraicRoot):
            active_variables.append(variable)
            active_samples.append(sample)
        else:
            raise TypeError(f"unsupported CAD sample type: {type(sample).__name__}")

    specialized = sp.expand(poly.as_expr().subs(substitutions))
    if active_variables:
        fiber_variable = variables[len(prefix)]
        result: sp.Expr | TowerFiberSpecialization = TowerFiberSpecialization(
            specialized,
            tuple((*active_variables, fiber_variable)),
            tuple(active_samples),
            fiber_variable,
        )
    else:
        result = specialized
    CACHE.specializations.put(key, result)
    return result


def _merge_ordered_root_streams(
    streams: Sequence[Sequence[AlgebraicRoot]],
) -> tuple[AlgebraicRoot, ...]:
    """K-way merge already ordered fiber-root families, deduplicating sections.

    Interval separation is handled inside ``compare_samples`` before any
    family-level resultant certificate is consulted.  This avoids re-sorting
    roots that ``isolate_real_roots`` has already returned in family order.
    """
    active = [list(stream) for stream in streams if stream]
    if active:
        from ..algebraic.comparison import prepare_shared_fiber_partition

        prepare_shared_fiber_partition(tuple(root for stream in active for root in stream))
    positions = [0] * len(active)
    merged: list[AlgebraicRoot] = []
    while True:
        candidates = [
            (stream[positions[index]], index)
            for index, stream in enumerate(active)
            if positions[index] < len(stream)
        ]
        if not candidates:
            break
        best, best_index = candidates[0]
        for candidate, index in candidates[1:]:
            try:
                order = compare_samples(candidate, best)
            except ArithmeticError:
                # Some algebraic-coefficient fibers still lack a complete
                # tower-order certificate. Preserve correctness by falling back
                # to the established sorter for the remaining roots only.
                remaining = list(merged)
                for stream_index, stream in enumerate(active):
                    remaining.extend(stream[positions[stream_index] :])
                return tuple(
                    root
                    for root in sort_samples(tuple(remaining))
                    if isinstance(root, AlgebraicRoot)
                )
            if order < 0:
                best, best_index = candidate, index
        positions[best_index] += 1
        if not merged or compare_samples(merged[-1], best) != 0:
            merged.append(best)
    return tuple(merged)


def _stack_roots_over_point(
    polys: Sequence[sp.Poly],
    variables: Sequence[sp.Symbol],
    prefix: Sequence[Sample],
    var: sp.Symbol,
    *,
    use_lazard: bool = False,
) -> tuple[AlgebraicRoot, ...]:
    streams: list[tuple[AlgebraicRoot, ...]] = []
    for poly in polys:
        context = (
            FiberRootContext(
                polynomial=poly,
                variables=tuple(variables[: len(prefix) + 1]),
                parent_samples=tuple(prefix),
                fiber_variable=var,
            )
            if prefix and not use_lazard
            else None
        )
        if context is not None:
            # Complete Collins lifting needs only the ordered real sections.
            # Isolate them directly over the certified parent tower; do not first
            # specialize parent algebraic samples into a global AlgebraicField.
            try:
                if context.is_nullified_at_parent():
                    continue
                parents = context.variables[:-1]
                point_values = {}
                for parent_var, sample in zip(parents, prefix, strict=True):
                    if isinstance(sample, RationalSample):
                        point_values[parent_var] = sample.value
                    elif sample.interval.is_point():
                        point_values[parent_var] = sample.interval.left
                if len(point_values) == len(parents):
                    family_poly = sp.Poly(
                        sp.expand(poly.as_expr().subs(point_values)), var, extension=True
                    )
                    ordinary_roots = isolate_real_roots(family_poly)
                    stream = tuple(
                        AlgebraicRoot(
                            family_poly, root.interval, index, root.multiplicity, None, context
                        )
                        for index, root in enumerate(ordinary_roots)
                    )
                else:
                    intervals = context.isolate_all_roots()
                    domain = sp.QQ.frac_field(*parents) if parents else sp.QQ
                    family_poly = sp.Poly(poly.as_expr(), var, domain=domain)
                    stream = tuple(
                        AlgebraicRoot(family_poly, interval, index, 1, None, context)
                        for index, interval in enumerate(intervals)
                    )
                if stream:
                    streams.append(stream)
                continue
            except (
                ArithmeticError,
                NotImplementedError,
                sp.PolynomialError,
                sp.polys.polyerrors.DomainError,
                ValueError,
                TypeError,
            ):
                # The fallback remains for unsupported coefficient operations,
                # but benchmark counters make any global-field use visible.
                CACHE.stats.number_field_fallbacks += 1

        if use_lazard and prefix:
            from .lifting.lazard import lazard_evaluate

            sample_prefix = [_sample_for_fiber_arithmetic(prefix[i]) for i in range(len(prefix))]
            expr = sp.expand(
                lazard_evaluate(poly.as_expr(), variables[: len(prefix)], sample_prefix).final_expr
            )
        else:
            specialized = _specialize_fiber_polynomial(poly, variables, prefix)
            if isinstance(specialized, TowerFiberSpecialization):
                tower_context = specialized.context()
                if tower_context.is_nullified_at_parent():
                    continue
                intervals = tower_context.isolate_all_roots()
                parents = specialized.variables[:-1]
                domain = sp.QQ.frac_field(*parents) if parents else sp.QQ
                family_poly = sp.Poly(specialized.expression, var, domain=domain)
                stream = tuple(
                    AlgebraicRoot(family_poly, interval, index, 1, None, tower_context)
                    for index, interval in enumerate(intervals)
                )
                if stream:
                    streams.append(stream)
                continue
            expr = specialized
        if expr == 0:
            continue
        try:
            univar = exact_univariate_poly(expr, var, algebraic_extension=False)
        except (sp.PolynomialError, TypeError, ValueError):
            continue
        if univar.degree() <= 0:
            continue
        fallback_context = (
            FiberRootContext(
                polynomial=poly,
                variables=tuple(variables[: len(prefix) + 1]),
                parent_samples=tuple(prefix),
                fiber_variable=var,
            )
            if prefix
            else None
        )
        stream = tuple(
            AlgebraicRoot(
                root.polynomial,
                root.interval,
                root.root_index,
                root.multiplicity,
                root.root_expr,
                fallback_context,
            )
            for root in isolate_real_roots(univar)
        )
        if stream:
            streams.append(stream)
    return _merge_ordered_root_streams(streams)


def _section_poly_for_root(
    level_polys: Sequence[sp.Poly],
    variables: Sequence[sp.Symbol],
    sample: Sequence[Sample],
    level: int,
) -> tuple[sp.Expr | None, str | None]:
    """Return the original tower polynomial defining a section sample.

    Testing the unspecialized polynomial with ``sign_at_sample`` preserves its
    provenance even when the base coordinates are algebraic.  Direct SymPy
    substitution can otherwise leave an opaque ordered-root expression that
    fails to simplify to zero, causing the section to be labelled only by its
    specialized fiber polynomial.
    """

    fiber_var = variables[level - 1]
    root = sample[-1] if sample else None
    if isinstance(root, AlgebraicRoot) and root.fiber_context is not None:
        defining = root.fiber_context.polynomial
        defining_key = _poly_key(defining)
        for poly in level_polys:
            if _poly_key(poly) == defining_key:
                return poly.as_expr(), defining_key
    for poly in level_polys:
        if fiber_var not in poly.as_expr().free_symbols:
            continue
        if sign_at_sample(poly, sample) == 0:
            return poly.as_expr(), _poly_key(poly)
    return None, None


def _build_stack(
    parent: CADCell | None, roots: Sequence[Sample], level: int, tower: ProjectionTower
) -> tuple[CADCell, ...]:
    """Lift one CAD stack over a parent cell from the ordered exact fiber roots."""
    variables = tower.variables
    prefix = parent.sample if parent is not None else tuple()
    parent_index = parent.index if parent is not None else tuple()
    level_polys = tower.level(level).polynomials
    cells: list[CADCell] = []
    bounds: list[Sample | None] = [None, *roots, None]
    position = 0
    for pos in range(len(bounds) - 1):
        left = bounds[pos]
        right = bounds[pos + 1]
        sector_sample = choose_sector_sample(left, right)
        sample = (*prefix, sector_sample)
        cells.append(
            CADCell(
                level=level,
                index=(*parent_index, position),
                sample=sample,
                interval=(left, right),
                signs=sign_table(level_polys, sample),
                kind="sector",
                parent_index=parent.index if parent is not None else None,
                stack_position=position,
            )
        )
        position += 1
        if right is not None:
            sample = (*prefix, right)
            section_expr, section_key = _section_poly_for_root(
                level_polys, variables, sample, level
            )
            if section_expr is None:
                section_expr = (
                    getattr(right, "polynomial", None).as_expr()
                    if isinstance(right, AlgebraicRoot)
                    else sp.Integer(0)
                )
            cells.append(
                CADCell(
                    level=level,
                    index=(*parent_index, position),
                    sample=sample,
                    interval=(right, right),
                    section_polynomial=section_expr,
                    signs=sign_table(level_polys, sample),
                    kind="section",
                    parent_index=parent.index if parent is not None else None,
                    stack_position=position,
                    root_index=pos,
                    defining_polynomial_key=section_key,
                )
            )
            position += 1
    return tuple(cells)


def _make_diagnostics(
    tower: ProjectionTower,
    cells_by_level: dict[int, tuple[CADCell, ...]],
    timings: Mapping[str, float],
) -> CADDiagnostics:
    check = verify_cad_sign_inv(cells_by_level, tower)
    temp = CompleteCAD(tower=tower, cells_by_level=cells_by_level)
    return CADDiagnostics(
        cell_count_by_level=temp.cell_count_by_level(),
        proj_poly_count_by_level=tower.poly_count_by_level(),
        max_stack_size=temp.max_stack_size(),
        timing_by_stage=dict(timings),
        invariant_failures=check.failures,
    )


def decomp_from_proj_tower(tower: ProjectionTower, *, backend: str | None = None) -> CompleteCAD:
    """Lift a CAD from an already-built projection tower.

    This is the common lifting engine used by the complete Collins path and by
    safe reduced-CAD attempts. Correctness is not inferred from this function
    alone: callers using reduced towers must attach a separate proof/fallback
    certificate.
    """

    timings: dict[str, float] = {"projection": 0.0}
    variables = tower.variables
    use_lazard = str(tower.metadata.get("projection", "")) == "lazard"
    cells_by_level: dict[int, tuple[CADCell, ...]] = {}
    if not variables:
        diagnostics = _make_diagnostics(tower, {0: tuple()}, timings)
        return CompleteCAD(
            tower=tower,
            cells_by_level={0: tuple()},
            backend=backend or str(tower.metadata.get("projection", "custom")),
            diagnostics=diagnostics,
        )
    lift_start = perf_counter()
    roots: list[AlgebraicRoot] = []
    for poly in tower.level(1).polynomials:
        roots.extend(isolate_real_roots(poly))
    cells_by_level[1] = _build_stack(None, sort_samples(tuple(roots)), 1, tower)
    for level in range(2, len(variables) + 1):
        next_cells: list[CADCell] = []
        for parent in cells_by_level[level - 1]:
            stack_roots = _stack_roots_over_point(
                tower.level(level).polynomials,
                variables,
                parent.sample,
                variables[level - 1],
                use_lazard=use_lazard,
            )
            next_cells.extend(_build_stack(parent, stack_roots, level, tower))
        cells_by_level[level] = tuple(next_cells)
    timings["lifting"] = perf_counter() - lift_start
    diag_start = perf_counter()
    diagnostics = _make_diagnostics(tower, cells_by_level, timings)
    timings["diagnostics"] = perf_counter() - diag_start
    diagnostics = CADDiagnostics(
        cell_count_by_level=diagnostics.cell_count_by_level,
        proj_poly_count_by_level=tower.poly_count_by_level(),
        max_stack_size=diagnostics.max_stack_size,
        timing_by_stage=timings,
        invariant_failures=diagnostics.invariant_failures,
    )
    return CompleteCAD(
        tower=tower,
        cells_by_level=cells_by_level,
        backend=backend or str(tower.metadata.get("projection", "custom")),
        diagnostics=diagnostics,
    )


def decomp_groebner_variety(
    projection: GroebnerVarietyProjection,
    *,
    lift_ops: GroebnerLiftOps | None = None,
) -> CompleteCAD:
    """Lift a section-only CAD of a certified zero-dimensional equality variety.

    The result is complete *on the common equality variety*, not a partition of
    all of real space.  It is therefore intended for formula decomposition when
    those equalities are necessary conditions for truth.
    """

    cells_by_level, timings = lift_groebner_variety(projection, ops=lift_ops)
    tower = projection.tower
    diagnostics = CADDiagnostics(
        cell_count_by_level={level: len(cells) for level, cells in cells_by_level.items()},
        proj_poly_count_by_level=tower.poly_count_by_level(),
        max_stack_size=CompleteCAD(tower=tower, cells_by_level=cells_by_level).max_stack_size(),
        timing_by_stage=timings,
        invariant_failures=(),
    )
    return CompleteCAD(
        tower=tower,
        cells_by_level=cells_by_level,
        complete=False,
        backend="groebner-variety",
        diagnostics=diagnostics,
    )


def try_decomp_groebner_variety(
    projection: GroebnerVarietyProjection,
    *,
    lift_ops: GroebnerLiftOps | None = None,
) -> CompleteCAD | None:
    """Return a certified variety CAD, or ``None`` when exact lifting declines."""

    try:
        return decomp_groebner_variety(projection, lift_ops=lift_ops)
    except VarietyCADUnsupported:
        return None


def decomp_collins_complete(
    polys: Sequence[sp.Expr | sp.Poly], variables: Sequence[sp.Symbol]
) -> CompleteCAD:
    """Construct a complete Collins CAD with exact projection, lifting, and diagnostic metadata."""
    vars_tuple = tuple(variables)
    if not vars_tuple:
        tower = ProjectionTower(
            variables=tuple(),
            levels=tuple(),
            original_polynomials=tuple(),
            metadata={"projection": "collins-complete", "zero_variable": True},
        )
        cell = CADCell(level=0, index=tuple(), sample=tuple(), kind="sector")
        diagnostics = CADDiagnostics(
            cell_count_by_level={0: 1},
            proj_poly_count_by_level={},
            max_stack_size=1,
            timing_by_stage={},
            invariant_failures=(),
        )
        return CompleteCAD(
            tower=tower,
            cells_by_level={0: (cell,)},
            backend="collins-complete",
            diagnostics=diagnostics,
        )
    try:
        input_polys = tuple(
            poly
            if isinstance(poly, sp.Poly) and tuple(poly.gens) == vars_tuple
            else sp.Poly(poly.as_expr() if isinstance(poly, sp.Poly) else poly, *vars_tuple)
            for poly in polys
        )
        cache_key = (polynomial_family_key(input_polys), vars_tuple)
    except (sp.PolynomialError, TypeError, ValueError):
        cache_key = None
    if cache_key is not None:
        cached = COMPLETE_CADS.get(cache_key)
        if cached is not None:
            STATS.complete_cad_hits += 1
            return cached  # type: ignore[return-value]
        STATS.complete_cad_misses += 1

    start = perf_counter()
    tower = build_collins_proj_set(polys, vars_tuple)
    projection_time = perf_counter() - start
    cad = decomp_from_proj_tower(tower, backend="collins-complete")
    timings = dict(cad.diagnostics.timing_by_stage if cad.diagnostics is not None else {})
    timings["projection"] = projection_time
    diagnostics = CADDiagnostics(
        cell_count_by_level=cad.cell_count_by_level(),
        proj_poly_count_by_level=tower.poly_count_by_level(),
        max_stack_size=cad.max_stack_size(),
        timing_by_stage=timings,
        invariant_failures=(
            cad.diagnostics.invariant_failures if cad.diagnostics is not None else ()
        ),
    )
    result = CompleteCAD(tower=tower, cells_by_level=cad.cells_by_level, diagnostics=diagnostics)
    if cache_key is not None:
        COMPLETE_CADS.put(cache_key, result)
    return result
